describe('PDF Inline Viewer', () => {
  beforeEach(() => {
    cy.visit('/pdf-upload');
  });

  it('should display uploaded PDF in inline viewer after successful upload', () => {
    // Intercept the PDF upload API
    cy.intercept('POST', '/api/upload/pdf', {
      statusCode: 200,
      body: {
        fileId: '12345',
        fileUrl: 'https://example.com/files/12345.pdf',
        status: 'success'
      }
    }).as('uploadPDF');

    // Upload a PDF file
    cy.get('[data-testid="pdf-upload-input"]').selectFile('cypress/fixtures/sample.pdf', {
      force: true
    });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload to complete
    cy.wait('@uploadPDF');

    // Verify success message appears
    cy.get('[data-testid="upload-success-message"]').should('be.visible').should('contain', 'PDF uploaded successfully');

    // Verify inline viewer is displayed
    cy.get('[data-testid="pdf-viewer"]').should('be.visible');
    cy.get('[data-testid="pdf-viewer"]').should('contain', 'sample.pdf');

    // Verify viewer shows correct file name
    cy.get('[data-testid="pdf-viewer-file-name"]').should('contain', 'sample.pdf');

    // Verify viewer shows file size
    cy.get('[data-testid="pdf-viewer-file-size"]').should('contain', '1.2 MB');

    // Verify viewer has correct file URL
    cy.get('[data-testid="pdf-viewer-file-url"]').should('contain', 'https://example.com/files/12345.pdf');
  });

  it('should display error message when PDF upload fails', () => {
    // Intercept the PDF upload API with error response
    cy.intercept('POST', '/api/upload/pdf', {
      statusCode: 500,
      body: {
        error: 'Internal server error',
        fileId: null
      }
    }).as('uploadPDFError');

    // Upload a PDF file
    cy.get('[data-testid="pdf-upload-input"]').selectFile('cypress/fixtures/sample.pdf', {
      force: true
    });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the failed upload
    cy.wait('@uploadPDFError');

    // Verify error message appears
    cy.get('[data-testid="upload-error-message"]').should('be.visible').should('contain', 'Upload failed');

    // Verify inline viewer is not displayed
    cy.get('[data-testid="pdf-viewer"]').should('not.exist');

    // Verify error message contains specific text
    cy.get('[data-testid="upload-error-message"]').should('contain', 'Internal server error');
  });
});
